    "description": "Based on Justine Levy's bestseller, \"Mauvaise Fille\" tells the story of 25 year-old Louise who learns in the course of one day that she is pregnant with her first child and that her mother is having a relapse of a deadly cancer. Louise's actor-boyfriend Pablo lives life to the fullest and is madly in love with her. Her father, a rock star, is constantly hopping from airplanes to luxury hotels to concert stages. As one life ends and another begins, Louise tries to finesse her way through a very delicate, difficult period. Her experiences are funny, sad and bittersweet. Like Justine Levy's books. And like life itself.",
